package dev.hollink.bankstanding.overlay;

import dev.hollink.bankstanding.BankstandingConfig;
import dev.hollink.bankstanding.config.ExperienceNotation;
import dev.hollink.bankstanding.domain.BankstandingLevel;
import dev.hollink.bankstanding.events.BankstandingEvent;
import dev.hollink.bankstanding.events.BankstandingEventBus;
import dev.hollink.bankstanding.events.BankstandingExperienceGainedEvent;
import dev.hollink.bankstanding.state.level.ExperienceManager;
import java.util.function.Consumer;
import net.runelite.api.Experience;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ExperienceOverlayStateManagerTest
{
	private BankstandingEventBus mockEventBus;
	private BankstandingConfig mockConfig;
	private ExperienceManager mockExperienceManager;

	private ExperienceOverlayStateManager stateManager;

	@Before
	public void setUp()
	{
		mockEventBus = mock(BankstandingEventBus.class);
		mockConfig = mock(BankstandingConfig.class);
		mockExperienceManager = mock(ExperienceManager.class);

		stateManager = new ExperienceOverlayStateManager(
			mockEventBus,
			mockConfig,
			mockExperienceManager
		);

		when(mockConfig.panelFadeTime()).thenReturn(10);
		when(mockConfig.showVirtualLevel()).thenReturn(false);
		when(mockConfig.experienceNotation()).thenReturn(ExperienceNotation.AUTO);
	}

	@Test
	public void init_shouldRegisterListener()
	{
		stateManager.init();

		verify(mockEventBus).register(any());
	}

	@Test
	public void destroy_shouldUnregisterListener()
	{
		stateManager.destroy();

		verify(mockEventBus).unregister(any());
	}

	@Test
	public void startUp_shouldInitializeState()
	{
		int lvl = 10;
		double xp = Experience.getXpForLevel(lvl);

		BankstandingLevel level = new BankstandingLevel(xp);
		when(mockExperienceManager.getBankstanding()).thenReturn(level);

		stateManager.startUp();

		assertEquals(lvl, stateManager.getCurrentLvl());
		assertEquals(0f, stateManager.getProgress(), 0.0001);
		assertEquals(java.time.Instant.EPOCH, stateManager.getLastExpDrop());
	}

	@Test
	public void event_shouldUpdateState_whenExperienceGained()
	{
		stateManager.init();

		Consumer<BankstandingEvent> listener = getRegisteredListener();

		int lvl = 10;
		double xp = Experience.getXpForLevel(lvl) + 100;

		BankstandingLevel level = new BankstandingLevel(xp);

		BankstandingExperienceGainedEvent event =
			mock(BankstandingExperienceGainedEvent.class);
		when(event.getSkill()).thenReturn(level);

		listener.accept(event);

		assertEquals(lvl, stateManager.getCurrentLvl());
		assertTrue(stateManager.getProgress() > 0);
		assertNotNull(stateManager.getLastExpDrop());
	}

	@Test
	public void event_shouldUseVirtualLevel_whenEnabled()
	{
		stateManager.init();

		when(mockConfig.showVirtualLevel()).thenReturn(true);

		Consumer<BankstandingEvent> listener = getRegisteredListener();

		BankstandingLevel level = mock(BankstandingLevel.class);
		when(level.getExperience()).thenReturn(10000.0);
		when(level.getCurrentVLevel()).thenReturn(99);

		BankstandingExperienceGainedEvent event =
			mock(BankstandingExperienceGainedEvent.class);
		when(event.getSkill()).thenReturn(level);

		listener.accept(event);

		assertEquals(99, stateManager.getCurrentLvl());
	}

	@Test
	public void hasRecentlyGainedExp_shouldBeTrue_afterEvent()
	{
		stateManager.init();

		Consumer<BankstandingEvent> listener = getRegisteredListener();

		BankstandingLevel level = new BankstandingLevel(10_000);
		BankstandingExperienceGainedEvent event = mock(BankstandingExperienceGainedEvent.class);
		when(event.getSkill()).thenReturn(level);

		listener.accept(event);

		assertTrue(stateManager.hasRecentlyGainedExp());
	}

	@Test
	public void hasRecentlyGainedExp_shouldBeFalse_afterStartupOnly()
	{
		BankstandingLevel level = new BankstandingLevel(0);
		when(mockExperienceManager.getBankstanding()).thenReturn(level);

		stateManager.startUp();

		assertFalse(stateManager.hasRecentlyGainedExp());
	}

	private Consumer<BankstandingEvent> getRegisteredListener()
	{
		ArgumentCaptor<Consumer<BankstandingEvent>> captor =
			ArgumentCaptor.forClass(Consumer.class);

		verify(mockEventBus).register(captor.capture());
		return captor.getValue();
	}
}

package dev.hollink.bankstanding.utils;

import dev.hollink.bankstanding.config.BankDistance;
import dev.hollink.bankstanding.config.BankLocation;
import java.util.Optional;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class BankDistanceFinderTest
{
	@Test
	public void getClosestBank_shouldReturnClosestBank()
	{
		WorldPoint testPoint = new WorldPoint(3092, 3245, 0);

		Optional<BankLocation> result = BankDistanceFinder.getCLosestBank(testPoint);

		assertTrue(result.isPresent());
		assertEquals(BankLocation.DRAYNOR, result.get());
	}

	@Test
	public void getClosestBank_shouldAlwaysReturnResult_whenBanksExist()
	{
		WorldPoint testPoint = new WorldPoint(0, 0, 0);

		Optional<BankLocation> result = BankDistanceFinder.getCLosestBank(testPoint);

		assertTrue(result.isPresent());
	}

	@Test
	public void getDistanceToBank_shouldReturnNowhereNear_whenBankIsNull()
	{
		WorldPoint point = new WorldPoint(0, 0, 0);

		BankDistance result = BankDistanceFinder.getDistanceToBank(null, point);

		assertEquals(BankDistance.NOWHERE_NEAR, result);
	}

	@Test
	public void getDistanceToBank_shouldReturnCorrectDistance()
	{
		BankLocation bank = BankLocation.VARROCK_WEST;
		WorldPoint point = bank.getCenterPoint();

		BankDistance result = BankDistanceFinder.getDistanceToBank(bank, point);

		assertEquals(BankDistance.INSIDE, result);
	}

	@Test
	public void getDistanceToBank_shouldReturnFarDistance()
	{
		BankLocation bank = BankLocation.VARROCK_WEST;

		WorldPoint point = new WorldPoint(
			bank.getCenterPoint().getX() + 100,
			bank.getCenterPoint().getY() + 100,
			bank.getCenterPoint().getPlane()
		);

		BankDistance result = BankDistanceFinder.getDistanceToBank(bank, point);

		assertEquals(BankDistance.NOWHERE_NEAR, result);
	}
}

package dev.hollink.bankstanding.utils;

import dev.hollink.bankstanding.config.ExperienceNotation;
import org.junit.Test;

import static dev.hollink.bankstanding.utils.ExperienceFormatter.valueOfExp;
import static org.junit.Assert.assertEquals;

public class ExperienceFormatterTest
{
	@Test
	public void shouldReturnFullValue_whenFullNotation()
	{
		assertEquals("123456", valueOfExp(123456, ExperienceNotation.FULL));
	}

	@Test
	public void shouldFormatK_withoutDecimal_whenExact()
	{
		assertEquals("2K", valueOfExp(2000, ExperienceNotation.K));
	}

	@Test
	public void shouldFormatK_withDecimal_whenNotExact()
	{
		assertEquals("2.5K", valueOfExp(2500, ExperienceNotation.K));
	}

	@Test
	public void shouldReturnRawValue_whenBelowKThreshold()
	{
		assertEquals("999", valueOfExp(999, ExperienceNotation.K));
	}

	@Test
	public void shouldFormatM_withoutDecimal_whenExact()
	{
		assertEquals("2M", valueOfExp(2_000_000, ExperienceNotation.M));
	}

	@Test
	public void shouldFormatM_withDecimal_whenNotExact()
	{
		assertEquals("2.5M", valueOfExp(2_500_000, ExperienceNotation.M));
	}

	@Test
	public void shouldReturnRawValue_whenBelowMThreshold()
	{
		assertEquals("999999", valueOfExp(999_999, ExperienceNotation.M));
	}

	@Test
	public void shouldReturnRaw_whenAutoBelow100K()
	{
		assertEquals("99999", valueOfExp(99_999, ExperienceNotation.AUTO));
	}

	@Test
	public void shouldUseK_whenAutoAt100K()
	{
		assertEquals("100K", valueOfExp(100_000, ExperienceNotation.AUTO));
	}

	@Test
	public void shouldUseK_whenAutoMidRange()
	{
		assertEquals("250K", valueOfExp(250_000, ExperienceNotation.AUTO));
	}

	@Test
	public void shouldUseM_whenAutoAt10M()
	{
		assertEquals("10M", valueOfExp(10_000_000, ExperienceNotation.AUTO));
	}

	@Test
	public void shouldUseM_withDecimal_whenAutoAbove10M()
	{
		assertEquals("12.5M", valueOfExp(12_500_000, ExperienceNotation.AUTO));
	}

	@Test
	public void shouldHandleZero()
	{
		assertEquals("0", valueOfExp(0, ExperienceNotation.AUTO));
	}
}

package dev.hollink.bankstanding.config;

import java.util.List;
import java.util.stream.Collectors;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.junit.Test;

import static dev.hollink.bankstanding.config.ActivityState.AFK;
import static dev.hollink.bankstanding.config.ActivityState.CHATTING;
import static dev.hollink.bankstanding.config.ActivityState.GRINDING;
import static dev.hollink.bankstanding.config.ActivityState.LOAFING;
import static dev.hollink.bankstanding.config.BankDistance.CLOSE;
import static dev.hollink.bankstanding.config.BankDistance.FAR;
import static dev.hollink.bankstanding.config.BankDistance.INSIDE;
import static dev.hollink.bankstanding.config.BankDistance.NEAR;
import static dev.hollink.bankstanding.config.BankDistance.NOWHERE_NEAR;
import static dev.hollink.bankstanding.config.BankDistance.VERY_CLOSE;
import static org.junit.Assert.assertTrue;

@Slf4j
public class ExpRateConstantsTest
{
	@Test
	public void shouldAwardGoodExpPerHourDependingOnStates()
	{
		List<Combination> testCases = List.of(
			new Combination(AFK, INSIDE, 14400),
			new Combination(CHATTING, INSIDE, 12960),
			new Combination(LOAFING, INSIDE, 3_600),
			new Combination(GRINDING, INSIDE, 0),
			new Combination(AFK, VERY_CLOSE, 11_520),
			new Combination(CHATTING, VERY_CLOSE, 10368),
			new Combination(LOAFING, VERY_CLOSE, 2880),
			new Combination(GRINDING, VERY_CLOSE, 0),
			new Combination(AFK, CLOSE, 8640),
			new Combination(CHATTING, CLOSE, 7776),
			new Combination(LOAFING, CLOSE, 2160),
			new Combination(GRINDING, CLOSE, 0),
			new Combination(AFK, NEAR, 3600),
			new Combination(CHATTING, NEAR, 3240),
			new Combination(LOAFING, NEAR, 900),
			new Combination(GRINDING, NEAR, 0),
			new Combination(AFK, FAR, 720),
			new Combination(CHATTING, FAR, 648),
			new Combination(LOAFING, FAR, 180),
			new Combination(GRINDING, FAR, 0),
			new Combination(AFK, NOWHERE_NEAR, 0),
			new Combination(CHATTING, NOWHERE_NEAR, 0),
			new Combination(LOAFING, NOWHERE_NEAR, 0),
			new Combination(GRINDING, NOWHERE_NEAR, 0)
		);

		List<String> failedTests = testCases.stream()
			.filter(tc -> tc.expPerHour() != tc.expectedHourlyExpRate)
			.map(Combination::reason)
			.collect(Collectors.toList());

		failedTests.forEach(log::info);
		assertTrue("There are testcases that fail, see preceding logs...", failedTests.isEmpty());
	}

	@RequiredArgsConstructor
	public static class Combination
	{
		private final ActivityState state;
		private final BankDistance distance;
		private final double expectedHourlyExpRate;

		public double expPerHour()
		{
			double expPerAction = ExpRateConstants.calculateExpGain(state, distance);
			long actionsPerHour = 3600 / ExpRateConstants.TIME_BETWEEN_DROPS.getSeconds();

			return Math.round(expPerAction * actionsPerHour);
		}

		public String reason()
		{
			return String.format("State %s with a %s distance should give %.0f xp/h but was %.0f", state, distance, expectedHourlyExpRate, this.expPerHour());
		}
	}
}

package dev.hollink.bankstanding.state.player;

import dev.hollink.bankstanding.config.ActivityState;
import dev.hollink.bankstanding.domain.PlayerState;
import dev.hollink.bankstanding.events.BankstandingEvent;
import dev.hollink.bankstanding.events.BankstandingEventBus;
import dev.hollink.bankstanding.events.BankstandingPlayerStateChangedEvent;
import java.time.Instant;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static dev.hollink.bankstanding.config.BankLocation.GRAND_EXCHANGE;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.reset;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class PlayerStateManagerTest
{
	private Client mockClient;
	private BankstandingEventBus mockEventBus;
	private PlayerStateManager playerStateManager;
	private Player mockPlayer;

	@Before
	public void setUp()
	{
		mockClient = mock(Client.class);
		mockEventBus = mock(BankstandingEventBus.class);

		mockPlayer = mock(Player.class);
		when(mockClient.getLocalPlayer()).thenReturn(mockPlayer);
		when(mockPlayer.getName()).thenReturn("TestPlayer");
		when(mockPlayer.getWorldLocation()).thenReturn(GRAND_EXCHANGE.getCenterPoint());

		playerStateManager = new PlayerStateManager(mockClient, mockEventBus);
		playerStateManager.startUp();

		// Set null state way back to skip the grace period.
		playerStateManager.setCurrentPlayerState(new PlayerState(Instant.EPOCH, ActivityState.NULL));
	}

	@Test
	public void onChatMessage_shouldUpdateLastChatMessage_ifFromPlayer()
	{
		when(mockPlayer.getName()).thenReturn("TestPlayer");

		ChatMessage mockMessage = mock(ChatMessage.class);
		when(mockMessage.getType()).thenReturn(net.runelite.api.ChatMessageType.PUBLICCHAT);
		when(mockMessage.getName()).thenReturn("TestPlayer");

		Instant before = playerStateManager.getLastChatMessage().getTime();

		playerStateManager.onChatMessage(mockMessage);

		Instant after = playerStateManager.getLastChatMessage().getTime();
		assertTrue(after.isAfter(before));
	}

	@Test
	public void onChatMessage_shouldNotUpdate_ifWrongPlayerOrType()
	{
		ChatMessage mockMessage = mock(ChatMessage.class);
		when(mockMessage.getType()).thenReturn(net.runelite.api.ChatMessageType.MODCHAT); // ignored type
		when(mockMessage.getName()).thenReturn("OtherPlayer");

		Instant before = playerStateManager.getLastChatMessage().getTime();

		playerStateManager.onChatMessage(mockMessage);

		Instant after = playerStateManager.getLastChatMessage().getTime();
		assertEquals(before, after);
	}

	@Test
	public void checkForStateChanges_shouldPublishEvent_whenActivityChanges()
	{
		when(mockClient.getOverallExperience()).thenReturn(100L);

		ArgumentCaptor<BankstandingEvent> captor = ArgumentCaptor.forClass(BankstandingEvent.class);

		playerStateManager.checkForStateChanges();

		verify(mockEventBus).publish(captor.capture());

		assertEquals(ActivityState.GRINDING, playerStateManager.getCurrentPlayerState().getActivity());
		assertTrue(captor.getValue() instanceof BankstandingPlayerStateChangedEvent);
	}

	@Test
	public void checkForStateChanges_shouldNotPublishEvent_ifActivitySame()
	{
		// the first check will update from NULL to AFK.
		playerStateManager.checkForStateChanges();
		ActivityState current = playerStateManager.getCurrentPlayerState().getActivity();
		reset(mockEventBus);

		playerStateManager.checkForStateChanges();

		verify(mockEventBus, never()).publish(any());
		assertEquals(current, playerStateManager.getCurrentPlayerState().getActivity());
	}

	@Test
	public void movementUpdate_shouldUpdateLastMovement_ifDistanceExceeded()
	{
		WorldPoint startLocation = GRAND_EXCHANGE.getCenterPoint();
		WorldPoint movedLocation = new WorldPoint(startLocation.getX() + 10, startLocation.getY() - 10, 0);
		when(mockPlayer.getWorldLocation()).thenReturn(movedLocation);
		Instant before = playerStateManager.getLastMovement().getTime();

		playerStateManager.checkForStateChanges();

		Instant after = playerStateManager.getLastMovement().getTime();
		assertTrue(after.isAfter(before));
	}
}

package dev.hollink.bankstanding.state.bankstats;

import dev.hollink.bankstanding.BankstandingConfig;
import dev.hollink.bankstanding.BankstandingPlugin;
import dev.hollink.bankstanding.config.BankDistance;
import dev.hollink.bankstanding.config.BankLocation;
import dev.hollink.bankstanding.domain.BankStats;
import dev.hollink.bankstanding.panel.BankstandingPanel;
import dev.hollink.bankstanding.utils.BankDistanceFinder;
import java.util.Optional;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class BankStatsManagerTest
{
	private Client mockClient;
	private BankstandingPlugin mockPlugin;
	private BankstandingConfig mockConfig;
	private BankStatsManager bankStatsManager;
	private Player mockPlayer;
	private BankstandingPanel mockPanel;

	@Before
	public void setUp()
	{
		mockClient = mock(Client.class);
		mockPlugin = mock(BankstandingPlugin.class);
		mockConfig = mock(BankstandingConfig.class);
		mockPlayer = mock(Player.class);
		when(mockClient.getLocalPlayer()).thenReturn(mockPlayer);

		when(mockConfig.enableTracker()).thenReturn(true);

		mockPanel = mock(BankstandingPanel.class);
		when(mockPlugin.getBankStatsPanel()).thenReturn(mockPanel);

		bankStatsManager = new BankStatsManager(mockClient, mockPlugin, null, mockConfig, null); // ignore Gson/configManager
	}

	@Test
	public void onTick_shouldAddTickAndVisit_whenPlayerInsideBank()
	{
		BankLocation bankLocation = BankLocation.LUMBRIDGE;
		WorldPoint playerLocation = BankLocation.LUMBRIDGE.getCenterPoint();
		when(mockPlayer.getWorldLocation()).thenReturn(playerLocation);

		when(mockPlayer.getAnimation()).thenReturn(-1); // idle

		bankStatsManager.onTick();

		BankStats session = bankStatsManager.getSessionStats().get(bankLocation);
		BankStats allTime = bankStatsManager.getAllTimeStats().get(bankLocation);

		assertNotNull(session);
		assertNotNull(allTime);

		assertEquals(1, session.getTotalTicks());
		assertEquals(1, session.getVisits());
		assertEquals(1, allTime.getTotalTicks());
		assertEquals(1, allTime.getVisits());
	}

	@Test
	public void onTick_shouldCountActiveTick_whenAnimationIsNotIdle()
	{
		BankLocation bankLocation = BankLocation.LUMBRIDGE;
		WorldPoint playerLocation = BankLocation.LUMBRIDGE.getCenterPoint();
		when(mockPlayer.getWorldLocation()).thenReturn(playerLocation);

		when(mockPlayer.getAnimation()).thenReturn(1234); // active

		bankStatsManager.onTick();

		BankStats session = bankStatsManager.getSessionStats().get(bankLocation);
		assertEquals(1, session.getTotalTicks());
		assertEquals(0, session.getIdleTicks());
		assertEquals(1, session.getActiveTicks());
	}

	@Test
	public void onTick_shouldSkipTick_whenBankIsOpen_andExcludeBankOpenTrue()
	{
		when(mockConfig.excludeBankOpen()).thenReturn(true);
		Widget bankWidget = mock(Widget.class);
		when(bankWidget.isHidden()).thenReturn(false);
		when(mockClient.getWidget(InterfaceID.BANKMAIN, 0)).thenReturn(bankWidget);

		bankStatsManager.onTick();

		assertTrue(bankStatsManager.getSessionStats().isEmpty());
		assertTrue(bankStatsManager.getAllTimeStats().isEmpty());
	}
}

package dev.hollink.bankstanding.state.level;

import dev.hollink.bankstanding.BankstandingConfig;
import dev.hollink.bankstanding.domain.BankstandingLevel;
import dev.hollink.bankstanding.events.BankstandingEvent;
import dev.hollink.bankstanding.events.BankstandingEventBus;
import dev.hollink.bankstanding.events.BankstandingExperienceGainedEvent;
import dev.hollink.bankstanding.overlay.ConfettiOverlay;
import java.time.Duration;
import java.util.function.Consumer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.SoundEffectID;
import net.runelite.client.plugins.bank.BankConfig;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.mockito.Mockito.any;
import static org.mockito.Mockito.anyInt;
import static org.mockito.Mockito.eq;
import static org.mockito.Mockito.isNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class LevelUpHandlerTest
{
	private Client mockClient;
	private BankstandingEventBus mockEventBus;
	private ConfettiOverlay mockConfetti;
	private BankstandingConfig mockConfig;

	private LevelUpHandler levelUpHandler;

	@Before
	public void setUp()
	{
		mockClient = mock(Client.class);
		mockEventBus = mock(BankstandingEventBus.class);
		mockConfetti = mock(ConfettiOverlay.class);
		mockConfig = mock(BankstandingConfig.class);

		levelUpHandler = new LevelUpHandler(mockClient, mockEventBus, mockConfetti, mockConfig);
	}

	@Test
	public void init_shouldRegisterListener()
	{
		levelUpHandler.init();

		verify(mockEventBus).register(any());
	}

	@Test
	public void destroy_shouldUnregisterListener()
	{
		levelUpHandler.destroy();

		verify(mockEventBus).unregister(any());
	}

	@Test
	public void event_shouldTriggerLevelUpBehavior_whenLeveledUp()
	{
		when(mockConfig.showLevelUpConfetti()).thenReturn(true);
		when(mockConfig.showLevelUpMessage()).thenReturn(true);
		when(mockConfig.playLevelUpSfx()).thenReturn(true);

		levelUpHandler.init();

		Consumer<BankstandingEvent> listener = getRegisteredListener();

		BankstandingLevel level = mock(BankstandingLevel.class);
		when(level.getCurrentLevel()).thenReturn(10);

		BankstandingExperienceGainedEvent xpEvent = mock(BankstandingExperienceGainedEvent.class);
		when(xpEvent.isLeveledUp()).thenReturn(true);
		when(xpEvent.getSkill()).thenReturn(level);

		listener.accept(xpEvent);

		verify(mockConfetti).trigger(Duration.ofSeconds(5));

		verify(mockClient).addChatMessage(
			eq(ChatMessageType.GAMEMESSAGE),
			eq(""),
			eq("You have leveled up your Bankstanding to level 10"),
			isNull()
		);

		verify(mockClient).playSoundEffect(SoundEffectID.GE_COIN_TINKLE);
	}

	@Test
	public void event_shouldNotTriggerLevelUp_whenNotLeveledUp()
	{
		levelUpHandler.init();

		Consumer<BankstandingEvent> listener = getRegisteredListener();

		BankstandingExperienceGainedEvent xpEvent = mock(BankstandingExperienceGainedEvent.class);
		when(xpEvent.isLeveledUp()).thenReturn(false);

		listener.accept(xpEvent);

		verify(mockConfetti, never()).trigger(any());
		verify(mockClient, never()).addChatMessage(any(), any(), any(), any());
		verify(mockClient, never()).playSoundEffect(anyInt());
	}

	private Consumer<BankstandingEvent> getRegisteredListener()
	{
		ArgumentCaptor<Consumer<BankstandingEvent>> captor =
			ArgumentCaptor.forClass(Consumer.class);
		verify(mockEventBus).register(captor.capture());
		return captor.getValue();
	}
}

package dev.hollink.bankstanding.state.level;

import dev.hollink.bankstanding.BankstandingConfig;
import dev.hollink.bankstanding.config.ActivityState;
import dev.hollink.bankstanding.config.BankDistance;
import dev.hollink.bankstanding.domain.PlayerState;
import dev.hollink.bankstanding.events.BankstandingEvent;
import dev.hollink.bankstanding.events.BankstandingEventBus;
import dev.hollink.bankstanding.events.BankstandingExperienceGainedEvent;
import dev.hollink.bankstanding.events.BankstandingPlayerStateChangedEvent;
import java.time.Instant;
import java.util.function.Consumer;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static dev.hollink.bankstanding.config.BankLocation.GRAND_EXCHANGE;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.any;
import static org.mockito.Mockito.anyString;
import static org.mockito.Mockito.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.reset;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ExperienceManagerTest
{
	private Client mockClient;
	private ConfigManager mockConfigManager;
	private BankstandingEventBus mockEventBus;
	private BankstandingConfig mockConfig;
	private Player mockPlayer;

	private ExperienceManager experienceManager;

	@Before
	public void setUp()
	{
		mockClient = mock(Client.class);
		mockConfigManager = mock(ConfigManager.class);
		mockEventBus = mock(BankstandingEventBus.class);
		mockConfig = mock(BankstandingConfig.class);
		when(mockConfig.enableLeveling()).thenReturn(true);

		mockPlayer = mock(Player.class);
		when(mockPlayer.getName()).thenReturn("TestPlayer");
		when(mockPlayer.getWorldLocation()).thenReturn(GRAND_EXCHANGE.getCenterPoint());
		when(mockClient.getLocalPlayer()).thenReturn(mockPlayer);

		experienceManager = new ExperienceManager(mockClient, mockConfigManager, mockEventBus, mockConfig);
	}

	@After
	public void tearDown()
	{
		reset(mockClient, mockConfigManager, mockEventBus);
	}

	@Test
	public void init_shouldRegisterListener()
	{
		experienceManager.init();
		verify(mockEventBus).register(any());
	}

	@Test
	public void destroy_shouldUnregisterListener()
	{
		experienceManager.destroy();
		verify(mockEventBus).unregister(any());
	}

	@Test
	public void startUp_shouldLoadStoredExperience()
	{
		when(mockConfigManager.getRSProfileConfiguration(anyString(), anyString()))
			.thenReturn("1500");

		experienceManager.startUp();

		assertEquals(1500.0, experienceManager.getBankstanding().getExperience(), 0.01);
	}

	@Test
	public void listener_shouldUpdateStateFields_onStateChangeEvent()
	{
		experienceManager.init();

		Consumer<BankstandingEvent> listener = getRegisteredListener();

		ActivityState oldActivity = ActivityState.LOAFING;
		Instant startTime = Instant.now();
		ActivityState newActivity = ActivityState.AFK;
		Instant newTimestamp = startTime.plusSeconds(100);

		BankstandingPlayerStateChangedEvent mockEvent = mock(BankstandingPlayerStateChangedEvent.class);
		when(mockEvent.getOldState()).thenReturn(new PlayerState(startTime, newActivity));
		when(mockEvent.getNewState()).thenReturn(new PlayerState(newTimestamp, oldActivity));

		listener.accept(mockEvent);

		assertEquals(oldActivity, experienceManager.getLastState());
		assertEquals(newTimestamp, experienceManager.getLastStateChange());
		assertEquals(newTimestamp, experienceManager.getLastExpDrop());
	}

	@Test
	public void listener_shouldDoNothing_ifEventIsNullOrWrongType()
	{
		experienceManager.init();

		Consumer<BankstandingEvent> listener = getRegisteredListener();

		ActivityState initialState = experienceManager.getLastState();
		Instant initialExpDrop = experienceManager.getLastExpDrop();
		Instant initialStateChange = experienceManager.getLastStateChange();

		listener.accept(null);
		listener.accept(mock(BankstandingEvent.class));

		assertEquals(initialState, experienceManager.getLastState());
		assertEquals(initialExpDrop, experienceManager.getLastExpDrop());
		assertEquals(initialStateChange, experienceManager.getLastStateChange());
	}

	@Test
	public void grantExperience_shouldIncreaseExperience_publishEventAndUpdateConfig()
	{
		experienceManager.startUp();

		when(mockClient.getLocalPlayer()).thenReturn(mockPlayer);

		experienceManager.grantExperience(ActivityState.AFK);

		verify(mockConfigManager).setRSProfileConfiguration(
			eq("Bankstanding"),
			eq("current_experience"),
			anyString()
		);

		ArgumentCaptor<BankstandingEvent> captor = ArgumentCaptor.forClass(BankstandingEvent.class);
		verify(mockEventBus).publish(captor.capture());
		BankstandingEvent event = captor.getValue();
		assertTrue(event instanceof BankstandingExperienceGainedEvent);

		double experience = experienceManager.getBankstanding().getExperience();

		assertTrue(experience > 0);
	}

	@Test
	public void getBankDistance_shouldReturnNowhereNear_ifNoPlayer()
	{
		when(mockClient.getLocalPlayer()).thenReturn(null);

		BankDistance bankDistance = experienceManager.getBankDistance();

		assertEquals(BankDistance.NOWHERE_NEAR, bankDistance);
	}

	@Test
	public void getBankDistance_shouldReturnSomeDistance_whenPlayerPresent()
	{
		var mockPlayer = mock(Player.class);
		when(mockPlayer.getName()).thenReturn("TestPlayer");
		when(mockPlayer.getWorldLocation()).thenReturn(GRAND_EXCHANGE.getCenterPoint());
		when(mockClient.getLocalPlayer()).thenReturn(mockPlayer);

		BankDistance bankDistance = experienceManager.getBankDistance();

		assertEquals(BankDistance.INSIDE, bankDistance);
	}

	private Consumer<BankstandingEvent> getRegisteredListener()
	{
		ArgumentCaptor<Consumer<BankstandingEvent>> captor =
			ArgumentCaptor.forClass(Consumer.class);
		verify(mockEventBus).register(captor.capture());
		return captor.getValue();
	}
}

