package dev.hollink.bankstanding.overlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class ConfettiOverlay extends Overlay
{
	private final Client client;

    private final List<ConfettiParticle> particles = new ArrayList<>();
	private static final Random random = new Random();

	private Instant endTime;

    public void trigger(Duration duration)
    {
		log.debug("Triggering confetti particles for {}s", duration.toSeconds());
        particles.clear();

        for (int i = 0; i < 250; i++)
        {
            ConfettiParticle p = new ConfettiParticle();
            p.x = random.nextInt(client.getCanvasWidth());
            p.y = -random.nextInt(200);
            p.velocityY = 2 + random.nextInt(4);
            p.color = new Color(
                random.nextInt(255),
                random.nextInt(255),
                random.nextInt(255)
            );
            particles.add(p);
        }

        endTime = Instant.now().plus(duration);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (endTime == null || Instant.now().isAfter(endTime))
        {
            return null;
        }

        for (ConfettiParticle p : particles)
        {
            p.update();
            graphics.setColor(p.color);
            graphics.fillRect(p.x, p.y, 4, 4);
        }

        return null;
    }

	private static class ConfettiParticle
	{
		int x;
		int y;
		int velocityY;
		Color color;

		public void update()
		{
			y += velocityY;
			x += random.nextInt(5) - 2;
		}
	}
}

package dev.hollink.bankstanding.overlay;

import dev.hollink.bankstanding.BankstandingConfig;
import dev.hollink.bankstanding.state.level.ExperienceManager;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.overlay.OverlayPanel;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class ExperienceOverlay extends OverlayPanel implements OverlayHelper
{
	private final ExperienceManager experienceManager;
	private final ExperienceOverlayStateManager stateManager;
	private final BankstandingConfig config;

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showBankstandingExperienceOverlay())
		{
			return super.render(graphics);
		}

		// Don't render if player is too far away from a bank region.
		if (experienceManager.getBankDistance().ordinal() > config.panelHideDistance().ordinal())
		{
			return super.render(graphics);
		}

		if (stateManager.hasRecentlyGainedExp())
		{
			addExperienceOverlay();
		}

		return super.render(graphics);
	}


	private void addExperienceOverlay()
	{
		setPanelWidth(160, panelComponent);
		addPanelPadding(panelComponent);
		addText("Bankstanding", String.valueOf(stateManager.getCurrentLvl()), panelComponent);
		addLabelledText("Current xp:", stateManager.getCurrentXp(), panelComponent);
		addLabelledText("Xp to level:", stateManager.getXpToLevel(), panelComponent);
		addLineBreak(panelComponent);
		addProgressBar(stateManager.getProgress(), panelComponent);
	}
}

package dev.hollink.bankstanding.overlay;

import dev.hollink.bankstanding.BankstandingConfig;
import dev.hollink.bankstanding.config.BankLocation;
import dev.hollink.bankstanding.domain.BankStats;
import dev.hollink.bankstanding.state.bankstats.BankStatsManager;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.overlay.OverlayPanel;

import static dev.hollink.bankstanding.domain.BankStats.formatTicksToTime;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class BankStatsOverlay extends OverlayPanel implements OverlayHelper
{
	private final BankStatsManager bankStatsManager;
	private final BankstandingConfig config;

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showBankStatsOverlay())
		{
			return super.render(graphics);
		}

		Optional<BankLocation> currentBank = bankStatsManager.getBankLocation();
		if (currentBank.isPresent())
		{
			BankLocation bankLocation = currentBank.get();
			BankStats session = bankStatsManager.getSessionStats().getOrDefault(bankLocation, new BankStats());

			addBankingData(bankLocation, session);
		}

		return super.render(graphics);
	}

	private void addBankingData(BankLocation bankLocation, BankStats session)
	{
		setPanelWidth(160, panelComponent);
		addTitle(bankLocation.getDisplayName(), panelComponent);
		addLineBreak(panelComponent);
		addLabelledText("Session", formatTicksToTime(session.getTotalTicks()), panelComponent);
		addLabelledText("Idle", formatTicksToTime(session.getIdleTicks()) + "  (" + session.idlePercent() + "%)", panelComponent);
		addLabelledText("Active", formatTicksToTime(session.getActiveTicks()) + "  (" + session.activePercent() + "%)", panelComponent);
		addLabelledText("Visits", String.valueOf(session.getVisits()), panelComponent);
	}
}

package dev.hollink.bankstanding.overlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Arrays;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public interface OverlayHelper
{

	default void setPanelWidth(int width, PanelComponent panel)
	{
		panel.setPreferredSize(new Dimension(width, 0));
	}

	default void addPanelPadding(PanelComponent panel)
	{
		panel.setBorder(new Rectangle(6, 4, 6, 4));
	}

	default void addTitle(String title, PanelComponent panel) {
		panel.getChildren().add(
			TitleComponent.builder()
				.text(title)
				.color(Color.WHITE)
				.build()
		);
	}

	default void addLabelledText(String left, String right, PanelComponent panel)
	{
		panel.getChildren().add(LineComponent.builder()
			.left(left).leftColor(Color.YELLOW)
			.right(right).rightColor(Color.WHITE)
			.build());
	}

	default void addText(String left, String right, PanelComponent panel)
	{
		panel.getChildren().add(LineComponent.builder()
			.left(left).leftColor(Color.WHITE)
			.right(right).rightColor(Color.WHITE)
			.build());
	}

	default void addRightOnlyText(String right, PanelComponent panel)
	{
		panel.getChildren().add(LineComponent.builder()
			.right(right).rightColor(Color.WHITE)
			.build());
	}

	default void addLineBreak(PanelComponent panel) {
		panel.getChildren().add(LineComponent.builder().build());
	}

	default void addProgressBar(float progress, PanelComponent panel)
	{
		panel.getChildren().add(buildProgressBarComponent(progress));
	}

	private ProgressBarComponent buildProgressBarComponent(float percentage)
	{
		ProgressBarComponent progressBar = new ProgressBarComponent();
		progressBar.setMinimum(0);
		progressBar.setMaximum(1);
		progressBar.setValue(percentage);
		progressBar.setForegroundColor(Color.GREEN);
		return progressBar;
	}
}

package dev.hollink.bankstanding.overlay.debug;

import dev.hollink.bankstanding.BankstandingConfig;
import dev.hollink.bankstanding.config.BankLocation;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Slf4j
@Singleton
public class BankLocationDebugOverlay extends Overlay
{
	private static final Color IN_BANK = new Color(181, 255, 105, 200);
	private static final Color NOT_IN_BANK = new Color(255, 181, 105, 200);

	private final Client client;
	private final BankstandingConfig config;

	@Inject
	public BankLocationDebugOverlay(Client client, BankstandingConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.bankHighlight())
		{
			return null;
		}

		for (BankLocation bank : BankLocation.values())
		{
			renderBankArea(graphics, bank);
		}

		return null;
	}

	private void renderBankArea(Graphics2D graphics, BankLocation bank)
	{
		WorldPoint player = client.getLocalPlayer().getWorldLocation();
		if (bank.getCenterPoint().getPlane() != player.getPlane())
		{
			return;
		}

		WorldArea bankArea = fromCenter(bank.getCenterPoint(), bank.getSize());
		Color overlayColor = bank.contains(player) ? IN_BANK : NOT_IN_BANK;

		renderWorldAreaOutline(graphics, bankArea, overlayColor);
		renderTile(graphics, bank.getCenterPoint(), overlayColor);
	}

	public static WorldArea fromCenter(WorldPoint center, int size)
	{
		return new WorldArea(center.getX() - size, center.getY() - size, size * 2, size * 2, center.getPlane());
	}

	private void renderWorldAreaOutline(Graphics2D graphics, WorldArea area, Color color)
	{
		int x1 = area.getX();
		int y1 = area.getY();
		int x2 = x1 + area.getWidth();
		int y2 = y1 + area.getHeight();
		int plane = area.getPlane();

		WorldPoint sw = new WorldPoint(x1, y1, plane);
		WorldPoint nw = new WorldPoint(x1, y2, plane);
		WorldPoint ne = new WorldPoint(x2, y2, plane);
		WorldPoint se = new WorldPoint(x2, y1, plane);

		LocalPoint lsw = LocalPoint.fromWorld(client, sw);
		LocalPoint lnw = LocalPoint.fromWorld(client, nw);
		LocalPoint lne = LocalPoint.fromWorld(client, ne);
		LocalPoint lse = LocalPoint.fromWorld(client, se);

		if (lsw == null || lnw == null || lne == null || lse == null)
		{
			return;
		}

		Polygon poly = new Polygon();

		addPoint(poly, lsw);
		addPoint(poly, lnw);
		addPoint(poly, lne);
		addPoint(poly, lse);

		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(2));
		graphics.drawPolygon(poly);
	}

	private void addPoint(Polygon poly, LocalPoint lp)
	{
		Point p = Perspective.localToCanvas(client, lp, client.getWorldView(lp.getWorldView()).getPlane());
		if (p != null)
		{
			poly.addPoint(p.getX(), p.getY());
		}
	}

	private void renderTile(Graphics2D graphics, WorldPoint worldPoint, Color color)
	{
		LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
		if (localPoint == null)
		{
			return;
		}

		Polygon poly = Perspective.getCanvasTilePoly(client, localPoint);
		if (poly == null)
		{
			return;
		}

		graphics.setColor(color);
		graphics.fillPolygon(poly);

		graphics.setColor(color);
		graphics.drawPolygon(poly);
	}
}

package dev.hollink.bankstanding.overlay.debug;

import dev.hollink.bankstanding.BankstandingConfig;
import dev.hollink.bankstanding.domain.Activity;
import dev.hollink.bankstanding.domain.PlayerState;
import dev.hollink.bankstanding.overlay.OverlayHelper;
import dev.hollink.bankstanding.state.level.ExperienceManager;
import dev.hollink.bankstanding.state.player.PlayerStateManager;
import dev.hollink.bankstanding.utils.BankDistanceFinder;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import java.time.Instant;
import java.util.Arrays;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.OverlayPanel;

import static dev.hollink.bankstanding.config.ExpRateConstants.TIME_BETWEEN_DROPS;
import static dev.hollink.bankstanding.config.TimeConstants.GRACE_PERIOD_CHATTING;
import static dev.hollink.bankstanding.config.TimeConstants.GRACE_PERIOD_GRINDING;
import static dev.hollink.bankstanding.config.TimeConstants.GRACE_PERIOD_MOVEMENT;
import static dev.hollink.bankstanding.config.TimeConstants.TIME_TILL_INITIAL_EXP;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class PlayerStateDebugOverlay extends OverlayPanel implements OverlayHelper
{
	private final Client client;
	private final BankstandingConfig config;

	private final PlayerStateManager stateManager;
	private final ExperienceManager xpManager;

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.displayDebugPanel())
		{
			return super.render(graphics);
		}

		setPanelWidth(160, panelComponent);
		addPanelPadding(panelComponent);
		addTitle("Bankstanding Debugger", panelComponent);
		addText("State:", enumToString(stateManager.getCurrentPlayerState().getActivity().name()), panelComponent);
		addText("Time left in state:", String.format("%ds", timeTillStateUpdates()), panelComponent);
		addClosestBankInfo();
		addText("Xp in:", String.format("%ds", timeTillExpDrop()), panelComponent);

		return super.render(graphics);
	}

	private void addClosestBankInfo()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		BankDistanceFinder.getCLosestBank(player.getWorldLocation())
			.ifPresentOrElse(bank -> {
				addText("Bank:", bank.getDisplayName(), panelComponent);
				addText("Distance:", enumToString(BankDistanceFinder.getDistanceToBank(bank, player.getWorldLocation()).name()), panelComponent);
			}, () -> {
				addText("Bank:", "-", panelComponent);
				addText("Distance:", "-", panelComponent);
			});
	}

	public long timeTillStateUpdates()
	{
		PlayerState currentPlayerState = stateManager.getCurrentPlayerState();
		switch (currentPlayerState.getActivity())
		{
			case NULL:
				return secondsSince(stateManager.getCurrentPlayerState().getSince(), TIME_TILL_INITIAL_EXP);
			case CHATTING:
				return secondsSince(stateManager.getLastChatMessage(), GRACE_PERIOD_CHATTING);
			case LOAFING:
				return secondsSince(stateManager.getLastMovement(), GRACE_PERIOD_MOVEMENT);
			case GRINDING:
				return secondsSince(stateManager.getLastExperienceDrop(), GRACE_PERIOD_GRINDING);
		}
		return 0;
	}

	public long timeTillExpDrop()
	{
		long secondsTillNextExpDrop = Duration.between(Instant.now(), xpManager.getLastExpDrop().plus(TIME_BETWEEN_DROPS)).toSeconds();
		return Math.max(secondsTillNextExpDrop, 0);
	}

	private long secondsSince(Instant from, Duration gracePeriod)
	{
		long secondsTillNextExpDrop = Duration.between(Instant.now(), from.plus(gracePeriod)).toSeconds();
		return Math.max(secondsTillNextExpDrop, 0);
	}

	private long secondsSince(Activity<?> activity, Duration gracePeriod)
	{
		return secondsSince(activity.getTime(), gracePeriod);
	}

	private String enumToString(String name)
	{
		return Arrays.stream(name.split("_"))
			.map(word -> word.charAt(0) + word.substring(1).toLowerCase())
			.collect(Collectors.joining(" "));
	}
}

package dev.hollink.bankstanding.overlay;

import dev.hollink.bankstanding.BankstandingConfig;
import dev.hollink.bankstanding.domain.BankstandingLevel;
import dev.hollink.bankstanding.events.BankstandingEvent;
import dev.hollink.bankstanding.events.BankstandingEventBus;
import dev.hollink.bankstanding.events.BankstandingExperienceGainedEvent;
import dev.hollink.bankstanding.state.level.ExperienceManager;
import dev.hollink.bankstanding.utils.ExperienceFormatter;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Experience;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
public class ExperienceOverlayStateManager
{
	private final BankstandingEventBus events;
	private final BankstandingConfig config;
	private final ExperienceManager experienceManager;

	@Getter
	private Instant lastExpDrop;
	@Getter
	private float progress;
	@Getter
	private int currentLvl;
	private int currentXp;
	private int xpToLevel;

	public void init()
	{
		events.register(this::onEvent);
	}

	public void destroy()
	{
		events.unregister(this::onEvent);
	}

	public void startUp()
	{
		BankstandingLevel bankstanding = experienceManager.getBankstanding();
		updateInternalState(bankstanding.getCurrentLevel(), bankstanding.getExperience());
		lastExpDrop = Instant.EPOCH;
	}

	public boolean hasRecentlyGainedExp()
	{
		Duration timeSinceLastExp = timeSinceLastExp();
		Duration fadeTime = fadeTime();

		return timeSinceLastExp.compareTo(fadeTime) <= 0;
	}

	public String getCurrentXp()
	{
		return ExperienceFormatter.valueOfExp(currentXp, config.experienceNotation());
	}

	public String getXpToLevel()
	{
		return ExperienceFormatter.valueOfExp(xpToLevel, config.experienceNotation());
	}

	private void onEvent(BankstandingEvent event)
	{
		if (event instanceof BankstandingExperienceGainedEvent)
		{
			BankstandingLevel bankstanding = ((BankstandingExperienceGainedEvent) event).getSkill();

			double experience = bankstanding.getExperience();
			int currentLevel = config.showVirtualLevel()
				? bankstanding.getCurrentVLevel()
				: bankstanding.getCurrentLevel();

			updateInternalState(currentLevel, experience);
		}
	}

	public void refreshExperience()
	{
		BankstandingLevel bankstanding = experienceManager.getBankstanding();
		updateInternalState(bankstanding.getCurrentLevel(), bankstanding.getExperience());
		lastExpDrop = Instant.now();
	}

	private void updateInternalState(int currentLevel, double currentExperience)
	{
		int xpAtStartOfLevel = Experience.getXpForLevel(currentLevel);
		int xpForNextLevel = Experience.getXpForLevel(currentLevel + 1);

		double xpIntoLevel = currentExperience - xpAtStartOfLevel;
		double xpRequiredForLevel = xpForNextLevel - xpAtStartOfLevel;

		if (xpRequiredForLevel <= 0)
		{
			return; // safety guard
		}

		// Clamp between 0 and 1 to avoid floating precision issues
		this.progress = Math.max(0f, Math.min(1f, (float) (xpIntoLevel / xpRequiredForLevel)));
		this.currentLvl = currentLevel;
		this.currentXp = (int) currentExperience;
		this.xpToLevel = (int) xpRequiredForLevel;
		this.lastExpDrop = Instant.now();
	}

	private Duration fadeTime()
	{
		int seconds = Math.max(config.panelFadeTime(), 10);
		return Duration.ofSeconds(seconds);
	}

	private Duration timeSinceLastExp()
	{
		return Duration.between(lastExpDrop, Instant.now());
	}
}

